// ============================================================
// ЗАКУПКА КУРТОШ v10 — Google Forms + Sheets, привязка по Tech_ID
// Скрипт должен быть привязан к таблице (Расширения → Apps Script)
// ============================================================

const POINTS = {
  Nijka:  {prefix: 'n', sheet: 'Закупка Нижка', formTitle: 'Закупка — Нижка'},
  Centre: {prefix: 'c', sheet: 'Закупка Центр', formTitle: 'Закупка — Центр'}
};
const PROPS = PropertiesService.getScriptProperties();
const COLS = 8;

// ============================================================
// 1. МЕНЮ
// ============================================================
function onOpen() {
  SpreadsheetApp.getUi().createMenu('⚙️ Управление')
    .addItem('🔃 Обновить данные сейчас', 'syncNow')
    .addItem('🧽 Очистить показания за сегодня', 'clearToday')
    .addItem('🔄 Начать новую неделю', 'newWeek')
    .addItem('📝 Обновить формы (новые товары, нормы)', 'updateForms')
    .addItem('🔗 Показать ссылки на формы', 'showFormLinks')
    .addItem('📖 Обновить инструкцию', 'createInstructionSheet')
    .addToUi();
}

// ============================================================
// 2. ПЕРВИЧНАЯ НАСТРОЙКА
// ============================================================
function setupAll() {
  setupSheets();
  install();
  setupForms();
}

function setupSheets() {
  const ss = SpreadsheetApp.getActive();
  Object.keys(POINTS).forEach(key => {
    const p = POINTS[key];
    const sh = ss.getSheetByName(p.sheet) || ss.insertSheet(p.sheet);
    if (sh.getLastRow() > 1) return;
    fillSheet(sh, getData(key), p.prefix);
  });
  if (!ss.getSheetByName('Журнал')) {
    const j = ss.insertSheet('Журнал');
    j.getRange(1, 1, 1, 4).setValues([['timestamp', 'point', 'tech_id', 'qty']]).setFontWeight('bold');
    j.getRange('A:A').setNumberFormat('dd.MM.yyyy HH:mm:ss');
    j.setFrozenRows(1);
  }
  createInstructionSheet(ss);
  const def = ss.getSheetByName('Лист1') || ss.getSheetByName('Sheet1');
  if (def && ss.getSheets().length > 1 && def.getLastRow() === 0) ss.deleteSheet(def);
  if (!PROPS.getProperty('WEEK_START')) PROPS.setProperty('WEEK_START', String(Date.now()));
}

function fillSheet(sheet, data, prefix) {
  const header = ['Наименование', 'Факт', 'Норма', 'Заказать', 'Поставщик', 'Tech_ID', 'Примечание', 'Обновлено'];
  const rows = [], catRows = [], itemRows = [];
  let cat = '', n = 0;
  data.forEach(item => {
    if (item.cat !== cat) {
      cat = item.cat;
      rows.push([cat, '', '', '', '', '', '', '']);
      catRows.push(rows.length + 1);
    }
    n++;
    const r = rows.length + 2;
    const note = (typeof item.norm === 'number') ? '' : String(item.norm);
    rows.push([item.name, '', parseNorm(item.norm), '', item.supplier, prefix + '_' + n, note, '']);
    itemRows.push(r);
  });
  sheet.getRange(1, 1, 1, COLS).setValues([header]).setFontWeight('bold').setBackground('#d9d2e9');
  sheet.getRange(2, 1, rows.length, COLS).setValues(rows);
  catRows.forEach(r => sheet.getRange(r, 1, 1, COLS).setFontWeight('bold').setBackground('#efefef'));
  const sep = getSep();
  itemRows.forEach(r => sheet.getRange(r, 4).setFormula(orderFormula(r, sep)));
  sheet.getRange(2, 8, rows.length, 1).setNumberFormat('dd.MM HH:mm');
  sheet.setColumnWidth(1, 250);
  sheet.setColumnWidth(7, 160);
  sheet.setFrozenRows(1);
  sheet.hideColumns(6);
}

function getSep() {
  const cached = PROPS.getProperty('SEP');
  if (cached) return cached;
  const ss = SpreadsheetApp.getActive();
  const t = ss.insertSheet('_tmp' + Date.now());
  let sep = ';';
  try {
    t.getRange('A1').setFormula('=IF(TRUE,1,2)');
    SpreadsheetApp.flush();
    if (t.getRange('A1').getValue() === 1) sep = ',';
  } finally {
    ss.deleteSheet(t);
  }
  PROPS.setProperty('SEP', sep);
  return sep;
}

function orderFormula(r, sep) {
  return '=IF(NOT(ISNUMBER(C' + r + '))' + sep + '""' + sep + 'IF(NOT(ISNUMBER(B' + r + '))' + sep + '"не считали"' + sep + 'MAX(0' + sep + 'C' + r + '-B' + r + ')))';
}

function parseNorm(v) {
  if (typeof v === 'number') return v;
  const m = String(v).replace(',', '.').match(/\d+(\.\d+)?/);
  return m ? Number(m[0]) : '';
}

// ============================================================
// 3. ФОРМЫ: создаются один раз, порциями
// ============================================================
function readRows(p) {
  const sh = SpreadsheetApp.getActive().getSheetByName(p.sheet);
  const n = sh.getLastRow() - 1;
  if (n < 1) return [];
  return sh.getRange(2, 1, n, COLS).getValues()
    .filter(r => r[0] !== '')
    .map(r => r[5] ? {id: r[5], name: r[0], norm: r[2], note: r[6]} : {section: r[0]});
}

function makeTitle(r) {
  const parts = [];
  if (r.norm !== '' && r.norm !== null) parts.push('норма: ' + r.norm);
  if (r.note) parts.push(r.note);
  return '[' + r.id + '] ' + r.name + (parts.length ? ' (' + parts.join(', ') + ')' : '');
}

function addRowToForm(form, r) {
  if (r.section) { form.addSectionHeaderItem().setTitle(r.section); return; }
  const item = form.addTextItem().setTitle(makeTitle(r)).setRequired(false);
  item.setValidation(FormApp.createTextValidation().requireNumber().setHelpText('Только числа').build());
}

function setupForms() {
  const BATCH = 20;
  let allDone = true;
  Object.keys(POINTS).forEach(key => {
    const p = POINTS[key];
    if (PROPS.getProperty('DONE_' + p.prefix)) return;
    let formId = PROPS.getProperty('FORM_' + p.prefix);
    let form;
    if (formId) {
      form = FormApp.openById(formId);
    } else {
      form = FormApp.create(p.formTitle);
      form.setDescription('Вводите ТОЛЬКО цифры. Если товара нет или не считали — оставьте поле пустым.');
      PROPS.setProperty('FORM_' + p.prefix, form.getId());
    }
    const rows = readRows(p);
    let pos = Number(PROPS.getProperty('POS_' + p.prefix) || 0);
    const end = Math.min(pos + BATCH, rows.length);
    while (pos < end) {
      addRowToForm(form, rows[pos]);
      pos++;
      PROPS.setProperty('POS_' + p.prefix, String(pos));
    }
    if (pos >= rows.length) PROPS.setProperty('DONE_' + p.prefix, '1'); else allDone = false;
  });

  ScriptApp.getProjectTriggers()
    .filter(t => t.getHandlerFunction() === 'setupForms')
    .forEach(t => ScriptApp.deleteTrigger(t));

  if (!allDone) {
    ScriptApp.newTrigger('setupForms').timeBased().after(60 * 1000).create();
    console.log('Продолжу через минуту...');
  } else {
    console.log('=== ФОРМЫ ГОТОВЫ ===');
    createInstructionSheet(SpreadsheetApp.getActive());
    Object.keys(POINTS).forEach(k => {
      const f = FormApp.openById(PROPS.getProperty('FORM_' + POINTS[k].prefix));
      console.log(POINTS[k].formTitle + ': ' + f.getPublishedUrl());
    });
  }
}

function showFormLinks() {
  let msg = '';
  Object.keys(POINTS).forEach(k => {
    const id = PROPS.getProperty('FORM_' + POINTS[k].prefix);
    if (id) msg += POINTS[k].formTitle + ':\n' + FormApp.openById(id).getPublishedUrl() + '\n\n';
  });
  SpreadsheetApp.getUi().alert(msg || 'Формы ещё не созданы. Запустите setupAll.');
}

function install() {
  ScriptApp.getProjectTriggers()
    .filter(t => t.getHandlerFunction() === 'syncResponses')
    .forEach(t => ScriptApp.deleteTrigger(t));
  ScriptApp.newTrigger('syncResponses').timeBased().everyMinutes(5).create();
}

// ============================================================
// 4. СИНХРОНИЗАЦИЯ: формы -> Журнал -> листы закупки
// ============================================================
function syncResponses() {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return null;
  try {
    return syncResponses_();
  } finally {
    lock.releaseLock();
  }
}

function syncResponses_() {
  const ss = SpreadsheetApp.getActive();
  const out = [], newLast = {};
  Object.keys(POINTS).forEach(key => {
    const p = POINTS[key];
    const formId = PROPS.getProperty('FORM_' + p.prefix);
    if (!formId) return;
    const form = FormApp.openById(formId);
    const idMap = {};
    form.getItems().forEach(it => {
      const m = it.getTitle().match(/^\[([a-z]_\d+)\]/);
      if (m) idMap[it.getId()] = m[1];
    });
    const last = Number(PROPS.getProperty('LAST_' + p.prefix) || 0);
    const resps = last ? form.getResponses(new Date(last)) : form.getResponses();
    let maxTs = last;
    resps.forEach(r => {
      const ts = r.getTimestamp();
      r.getItemResponses().forEach(ir => {
        const id = idMap[ir.getItem().getId()];
        const q = toNum(ir.getResponse());
        if (id && q !== null) out.push([ts, p.prefix, id, q]);
      });
      if (ts.getTime() > maxTs) maxTs = ts.getTime();
    });
    newLast[p.prefix] = maxTs;
  });
  if (out.length) {
    const j = ss.getSheetByName('Журнал');
    j.getRange(j.getLastRow() + 1, 1, out.length, 4).setValues(out);
  }
  Object.keys(newLast).forEach(k => PROPS.setProperty('LAST_' + k, String(newLast[k])));
  applyFacts();
  return {rows: out.length};
}

function syncNow() {
  const ui = SpreadsheetApp.getUi();
  try {
    const st = syncResponses();
    let msg = '';
    Object.keys(POINTS).forEach(k => {
      const p = POINTS[k];
      const id = PROPS.getProperty('FORM_' + p.prefix);
      if (!id) { msg += p.formTitle + ': форма не создана\n'; return; }
      const f = FormApp.openById(id);
      const q = f.getItems().filter(it => /^\[[a-z]_\d+\]/.test(it.getTitle())).length;
      msg += p.formTitle + ': вопросов с ID — ' + q + ', ответов в форме — ' + f.getResponses().length + '\n';
    });
    msg += '\nНовых записей добавлено в «Журнал»: ' + (st ? st.rows : 'синхронизация уже идёт, повторите') ;
    ui.alert(msg);
  } catch (e) {
    ui.alert('Ошибка: ' + e.message);
  }
}

function toNum(v) {
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  if (s === '') return null;
  const n = Number(s);
  return isNaN(n) ? null : n;
}

function applyFacts() {
  const ss = SpreadsheetApp.getActive();
  const weekStart = Number(PROPS.getProperty('WEEK_START') || 0);
  const j = ss.getSheetByName('Журнал');
  const rows = j.getLastRow() > 1 ? j.getRange(2, 1, j.getLastRow() - 1, 4).getValues() : [];
  const latest = {};
  rows.forEach(r => {
    const t = new Date(r[0]).getTime();
    if (t < weekStart) return;
    if (!latest[r[2]] || t >= latest[r[2]].t) latest[r[2]] = {t: t, q: r[3]};
  });
  Object.keys(POINTS).forEach(key => {
    const sh = ss.getSheetByName(POINTS[key].sheet);
    const n = sh.getLastRow() - 1;
    if (n < 1) return;
    const ids = sh.getRange(2, 6, n, 1).getValues();
    const facts = ids.map(r => [r[0] && latest[r[0]] ? latest[r[0]].q : '']);
    const dates = ids.map(r => [r[0] && latest[r[0]] ? new Date(latest[r[0]].t) : '']);
    sh.getRange(2, 2, n, 1).setValues(facts);
    sh.getRange(2, 8, n, 1).setValues(dates);
  });
}

function newWeek() {
  syncResponses();
  PROPS.setProperty('WEEK_START', String(Date.now()));
  applyFacts();
  SpreadsheetApp.getUi().alert('Новая неделя начата. История сохранена на листе «Журнал».');
}

function clearToday() {
  const ui = SpreadsheetApp.getUi();
  const ss = SpreadsheetApp.getActive();
  const tz = ss.getSpreadsheetTimeZone();
  const fmt = d => Utilities.formatDate(new Date(d), tz, 'yyyy-MM-dd');
  const today = fmt(new Date());
  const ans = ui.alert('Очистить показания за сегодня',
    'Будут удалены все показания, внесённые сегодня (' + today + ') на обеих точках.\n' +
    'Показания за другие дни останутся.\n\nПродолжить?', ui.ButtonSet.YES_NO);
  if (ans !== ui.Button.YES) return;

  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) { ui.alert('Идёт синхронизация, повторите через минуту.'); return; }
  try {
    syncResponses_();
    const j = ss.getSheetByName('Журнал');
    const last = j.getLastRow();
    let removed = 0;
    if (last > 1) {
      const data = j.getRange(2, 1, last - 1, 4).getValues();
      const keep = data.filter(r => fmt(r[0]) !== today);
      removed = data.length - keep.length;
      if (removed > 0) {
        j.getRange(2, 1, last - 1, 4).clearContent();
        if (keep.length) j.getRange(2, 1, keep.length, 4).setValues(keep);
      }
    }
    applyFacts();
    ui.alert('Удалено записей за сегодня: ' + removed + '.');
  } finally {
    lock.releaseLock();
  }
}

// ============================================================
// 5. ОБНОВЛЕНИЕ ФОРМ БЕЗ ПЕРЕСОЗДАНИЯ
// ============================================================
function updateForms() {
  const ss = SpreadsheetApp.getActive();
  Object.keys(POINTS).forEach(key => {
    const p = POINTS[key];
    assignMissingIDs(ss.getSheetByName(p.sheet), p.prefix);
    const formId = PROPS.getProperty('FORM_' + p.prefix);
    if (!formId) return;
    const form = FormApp.openById(formId);
    const existing = {};
    form.getItems().forEach(it => {
      const m = it.getTitle().match(/^\[([a-z]_\d+)\]/);
      if (m) existing[m[1]] = it;
    });
    readRows(p).forEach(r => {
      if (!r.id) return;
      const it = existing[r.id];
      if (it) {
        const t = makeTitle(r);
        if (it.getTitle() !== t) it.setTitle(t);
      } else {
        addRowToForm(form, r);
      }
    });
  });
  SpreadsheetApp.getUi().alert('Формы обновлены. Ссылки прежние, данные не потеряны.');
}

function assignMissingIDs(sheet, prefix) {
  const n = sheet.getLastRow() - 1;
  if (n < 1) return;
  const data = sheet.getRange(2, 1, n, COLS).getValues();
  let maxId = 0;
  data.forEach(r => {
    const m = String(r[5]).match(/_(\d+)$/);
    if (m) maxId = Math.max(maxId, Number(m[1]));
  });
  const col = data.map(r => {
    if (r[5]) return [r[5]];
    const name = String(r[0]);
    const isCat = name && r[2] === '' && r[4] === '' && r[6] === '' &&
                  name === name.toUpperCase() && name !== name.toLowerCase();
    if (!name || isCat) return [''];
    maxId++;
    return [prefix + '_' + maxId];
  });
  sheet.getRange(2, 6, n, 1).setValues(col);
  for (let i = 0; i < n; i++) {
    const r = i + 2;
    if (col[i][0] && !data[i][3]) {
      sheet.getRange(r, 4).setFormula(orderFormula(r, getSep()));
    }
  }
}

// ============================================================
// 6. ИНСТРУКЦИЯ
// ============================================================
function createInstructionSheet(ss) {
  if (!ss || typeof ss.getSheetByName !== 'function') ss = SpreadsheetApp.getActive();
  let sheet = ss.getSheetByName('📖 Инструкция');
  if (sheet) sheet.clear(); else sheet = ss.insertSheet('📖 Инструкция');
  sheet.setColumnWidth(1, 30);
  sheet.setColumnWidth(2, 650);

  const url = {};
  Object.keys(POINTS).forEach(k => {
    const id = PROPS.getProperty('FORM_' + POINTS[k].prefix);
    url[k] = id ? FormApp.openById(id).getPublishedUrl() : '';
  });

  const L = [
    ['ИНСТРУКЦИЯ ПО РАБОТЕ С ЗАКУПКАМИ (v10)', 'title'],
    ['', 'text'],
    ['ССЫЛКИ НА ФОРМЫ (для заполнения остатков):', 'h'],
    ['Нижка:', 'text'],
    [url.Nijka || 'форма ещё не создана', url.Nijka ? 'link' : 'text', url.Nijka],
    ['Центр:', 'text'],
    [url.Centre || 'форма ещё не создана', url.Centre ? 'link' : 'text', url.Centre],
    ['', 'text'],
    ['1. КАК ЗАПОЛНИТЬ ОСТАТКИ:', 'h'],
    ['• Откройте ссылку на форму своей точки (см. выше).', 'text'],
    ['• Вводите ТОЛЬКО цифры. Если не считали — оставьте поле пустым.', 'text'],
    ['• Нажмите «Отправить». Данные попадут в таблицу в течение 5 минут (или сразу по кнопке «Обновить данные сейчас»).', 'text'],
    ['• Если в колонке «Заказать» написано «не считали» — остаток на этой неделе не вводили.', 'text'],
    ['', 'text'],
    ['2. КАК ИСПРАВИТЬ ОШИБКУ ВВОДА:', 'h'],
    ['• «🧽 Очистить показания за сегодня» — удаляет ТОЛЬКО показания, внесённые сегодня (обе точки).', 'text'],
    ['• Показания за предыдущие дни недели остаются, «Факт» вернётся к последнему из них.', 'text'],
    ['• После очистки заполните форму заново.', 'text'],
    ['', 'text'],
    ['3. КАК НАЧАТЬ НОВУЮ НЕДЕЛЮ:', 'h'],
    ['• «🔄 Начать новую неделю» — «Факт» обнуляется, вся история остаётся на листе «Журнал».', 'text'],
    ['', 'text'],
    ['4. КАК ДОБАВИТЬ НОВЫЙ ТОВАР:', 'h'],
    ['• Добавьте строку в конец нужной категории: название (A), норму (C), поставщика (E).', 'text'],
    ['• В меню «⚙️ Управление» нажмите «📝 Обновить формы». ID выдастся автоматически.', 'text']
  ];

  const rng = sheet.getRange(1, 2, L.length, 1);
  rng.setValues(L.map(r => [r[0]])).setVerticalAlignment('middle').setWrap(true);
  L.forEach((r, i) => {
    const cell = sheet.getRange(i + 1, 2);
    if (r[1] === 'title') cell.setFontSize(16).setFontWeight('bold').setFontColor('#1c4587');
    else if (r[1] === 'h') cell.setFontSize(12).setFontWeight('bold').setFontColor('#cc0000');
    else if (r[1] === 'link') {
      cell.setRichTextValue(SpreadsheetApp.newRichTextValue().setText(r[0]).setLinkUrl(r[2]).build());
    }
  });
}

// ============================================================
// 7. БАЗА ДАННЫХ
// ============================================================
function getData(point) {
  const M = 'магнус', W = 'WB', S = 'С/Ж или Метро';
  const L = (cat, arr) => arr.map(a => ({cat: cat, name: a[0], norm: a[1], supplier: a[2]}));

  const nijka = [].concat(
    L('ХОЗКА', [
      ['стакан 100мл', 50, M], ['подставка на 2', 20, M], ['подставка на 4', 20, M],
      ['химия тачка', 1, M], ['химия паровик', 1, W], ['химия молка', 1, W],
      ['мешалки', '1уп', M], ['айс крышки', 200, M], ['айс стаканы 0.3', 200, M],
      ['айс стаканы 0.6', 54, M], ['порционный сахар', '1коробка', M],
      ['химия дезинфекция', 1, M], ['химия пол', 1, M], ['химия посуда', 1, M],
      ['химия мыло для рук', 1, M], ['пемолюкс', 1, M], ['трубочки', '1уп', M],
      ['кассовая лента', '5шт', M], ['стикер маркировка', 1, M], ['фольга', 1, M],
      ['перчатки S', 2, M], ['перчатки M', 2, M], ['перчатки L', 1, M], ['перчатки XL', 1, M],
      ['вафельное полотно', 1, M], ['влажн. салфетки', 1, M], ['пакет под калач', 1, M],
      ['пакет с собой', 1, M], ['пакет с ручкой', 1, M], ['мус. пакет 180л', 1, M],
      ['мус. пакет 35л', '2шт', M], ['тряпки губчатые', 2, M], ['губки', 2, M],
      ['железные губки', 1, M], ['фильтр пакет под чай', 1, M]
    ]),
    L('ПРОДУКТЫ', [
      ['сахар', 2, S], ['дрожжи', 40, S], ['корица', 1, S], ['ванилин', 1, 'С/Ж'],
      ['нутелла', 1, S], ['меланж', 2, S], ['какао', 2, S], ['кунжут', 1, S],
