      ['пюре облепиха', 1, S], ['пюре малина', 1, S], ['пюре черника', 1, S],
      ['молоко ЭКОНИВА 3.2', 48, S], ['молоко банан', 10, S], ['молоко кокос', 10, S],
      ['молоко миндаль', 10, S], ['молоко безлактозное', 10, S], ['сливки', 12, S],
      ['сок апельсин', 12, S], ['сок вишня', 12, S], ['сок персик', 12, S],
      ['бум. полотенца', '5уп', S], ['бум. салфетки', 30, S], ['туалетка', 12, S],
      ['мука', 12, S], ['масло', '2л', S], ['маршмеллоу', 2, S], ['клюква', 1, S],
